"""The repository tree matches PRD §10.2 / §10.3 plus the deviations of the migration plan (expected_tree.json, generated by tools/harness/prd_tree.py).

  python -m unittest harness/tests/architecture/test_tree.py
"""
import json
import unittest
from pathlib import Path

REPO = Path(__file__).resolve().parents[3]
EXPECTED = json.loads((Path(__file__).with_name("expected_tree.json")).read_text(encoding="utf-8"))
STATUSES = ("implemented", "in development", "planned")


class TreeMatchesPrd(unittest.TestCase):
    def test_every_expected_folder_exists(self):
        missing = [d["path"] for d in EXPECTED["dirs"] if not (REPO / d["path"]).is_dir()]
        self.assertEqual(missing, [])

    def test_every_expected_folder_says_what_it_is_and_its_status(self):
        for d in EXPECTED["dirs"]:
            with self.subTest(folder=d["path"]):
                readme = REPO / d["path"] / "README.md"
                self.assertTrue(readme.is_file(), f"{d['path']} has no README.md")
                text = readme.read_text(encoding="utf-8")
                self.assertTrue(any(f"Status: **{s}**" in text for s in STATUSES), f"{d['path']}/README.md has no valid status")

    def test_projects_holds_only_readme_and_template(self):
        names = sorted(p.name for p in (REPO / "projects").iterdir())
        self.assertEqual(names, ["README.md", "_template"])

    def test_the_template_has_no_client_data(self):
        for p in (REPO / "projects" / "_template").rglob("*"):
            if p.is_file():
                self.assertIn(p.suffix, (".md", ".txt", ".json"), p.as_posix())
                self.assertLess(p.stat().st_size, 20_000, p.as_posix())

    def test_the_template_has_the_prd_files_and_they_carry_no_client_data(self):
        import json
        base = REPO / "projects" / "_template" / ".epc"
        for name in ("project_profile.json", "master_project_state.json"):
            data = json.loads((base / name).read_text(encoding="utf-8"))
            self.assertEqual(data["status"], "template", name)
        profile = json.loads((base / "project_profile.json").read_text(encoding="utf-8"))
        self.assertIsNone(profile["project_code"])
        self.assertIsNone(profile["client"]["name"])
        self.assertTrue((base / "epc_progress.txt").is_file())

    def test_the_tree_names_the_prd_section(self):
        self.assertIn("§10.2", EXPECTED["source"])


if __name__ == "__main__":
    unittest.main()
